      if (path === '/admin/publications/new') { try { return { publicationDraft: await api.getDraft<PublicationData>('publication', newId, session) }; } catch (error) { if (!(error instanceof Error) || error.message !== 'This draft is unavailable.') throw error; return { publicationDraft: { id: newId, revision: 0, data: { ...emptyPublication } } }; } }
