export function ConnectedInterests({ session }: { session: Session }) {
  const [page, setPage] = useState<api.ContentPage<Interest>>({ items: [], nextCursor: null }), [cursors, setCursors] = useState<(string | null)[]>([null]), [error, setError] = useState(''), [loading, setLoading] = useState(true), [version, reload] = useState(0);
  useEffect(() => { let active = true; setLoading(true); setError(''); void api.listInterests(cursors[cursors.length - 1], session).then(result => { if (active && sessionResultIsCurrent(session)) setPage(result); }).catch(caught => { if (active) setError(caught instanceof Error ? caught.message : 'Interests are unavailable.'); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [session, cursors, version]);
  return <MemberInterests items={page.items} loading={loading} error={error} pageNumber={cursors.length} onPrevious={cursors.length > 1 ? () => setCursors(old => old.slice(0, -1)) : undefined} onNext={page.nextCursor ? () => setCursors(old => [...old, page.nextCursor]) : undefined} onWithdraw={async id => { await api.withdrawInterest(id, session); reload(value => value + 1); }} />;
}

export function ConnectedDiscover({ session, children }: { session: Session; children: (slides: { tag: string; title: string; description: string; href: string; image: string; alt: string }[] | undefined) => ReactNode }) {
  const [slides, setSlides] = useState<{ tag: string; title: string; description: string; href: string; image: string; alt: string }[] | undefined>();
  useEffect(() => {
    let active = true; const releases: (() => void)[] = [];
    if (session.status === 'loading' || session.status === 'unconfigured' || session.status === 'signing-out') return;
    void api.listPublished<DiscoverData>('discover', null, session).then(async page => {
      const result = [];
      for (const item of page.items) {
        let image = '/assets/' + item.data.defaultImage;
        if (item.data.image) { const lease = await api.loadAttachments('discover', item.id, [item.data.image], session); if (!active) { lease.release(); return; } releases.push(lease.release); image = lease.files[item.data.image]?.objectUrl || image; }
        const href = safeContentWebsite(item.data.websiteUrl); if (href) result.push({ tag: item.data.tag, title: item.data.title, description: item.data.description, href, image, alt: item.data.imageAlt });
      }
      if (active && sessionResultIsCurrent(session)) setSlides(result.length ? result : undefined);
    }).catch(() => { if (active) setSlides(undefined); });
    return () => { active = false; releases.forEach(release => release()); };
  }, [session]);
  return children(slides);
}
export function HomeEvents({ session }: { session: Session }) {
  const [items, setItems] = useState<ContentProjection<EventData>[]>([]), [error, setError] = useState(''), [loading, setLoading] = useState(true);
  useEffect(() => { let active = true; if (session.status === 'loading') return; void api.listPublished<EventData>('event', null, session).then(page => { if (active) setItems(page.items.slice(0, 3)); }).catch(() => { if (active) setError('Events are unavailable at the moment.'); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [session]);
  return <><ListingStatus loading={loading} error={error} />{!loading && !error && !items.length && <p className="form-hint">Published events will appear here as they become available.</p>}{items.map(event => <article className="event-teaser" key={event.id}><img src="/assets/event-palms.jpg" alt="" loading="lazy" /><div><span className="sample-label">{event.data.format}</span><h3>{event.data.title}</h3><p>{dateLabel(event.data.date)} · {feeLabel(event.data)}</p><Link href={'/events/' + event.id} className="link-button">View event<Icon name="chevron-right" /></Link></div></article>)}</>;
}

export function HomePublications({ session }: { session: Session }) {
  const [items, setItems] = useState<ContentProjection<PublicationData>[]>([]), [files, setFiles] = useState<Record<string, AttachmentView>>({}), [error, setError] = useState(''), [loading, setLoading] = useState(false);
  useEffect(() => {
    let active = true; const releases: (() => void)[] = [];
    if (!session.memberAccess) return;
    setItems([]); setFiles({}); setError(''); setLoading(true);
    void api.listPublished<PublicationData>('publication', null, session).then(async page => {
      const visible = page.items.slice(0, 3), resolved: Record<string, AttachmentView> = {};
      for (const item of visible) if (item.data.cover) { const lease = await api.loadAttachments('publication', item.id, [item.data.cover], session); if (!active) { lease.release(); return; } releases.push(lease.release); Object.assign(resolved, lease.files); }
      if (active && sessionResultIsCurrent(session)) { setItems(visible); setFiles(resolved); }
    }).catch(() => { if (active) setError('The member library is unavailable at the moment.'); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; releases.forEach(release => release()); };
  }, [session]);
  return <section className="home-section home-publications" aria-label="Member publications"><div className="section-head"><h2>Publications</h2><Icon name="journal-bookmark" /></div>{session.memberAccess ? <><p className="section-lede">Your next good read, from the ISP member library.</p><ListingStatus loading={loading} error={error} />{!loading && !error && !items.length && <div className="empty-state"><p>New issues will appear here when published.</p><Link href="/member/publications" className="link-button">Open your library</Link></div>}{items.map(item => <article className="publication-card" key={item.id}><Link href={'/member/publications/' + item.id} className="publication-cover-link">{item.data.cover && imageUrl(files[item.data.cover]) ? <img src={imageUrl(files[item.data.cover])} alt={item.data.title + ' cover'} loading="lazy" /> : <span className="form-hint">Cover unavailable</span>}</Link><div><span className="eyebrow">Member publication</span><h3>{item.data.title}</h3>{item.data.subtitle && <p className="publication-subtitle">{item.data.subtitle}</p>}<p>{item.data.description.slice(0, 160)}</p><Link href={'/member/publications/' + item.id} className="link-button">Read publication<Icon name="chevron-right" /></Link></div></article>)}{items.length > 0 && <Link href="/member/publications" className="link-button">View all publications</Link>}</> : session.adminClaim ? <><p className="section-lede">Publish the next issue for the member library.</p><Link href="/admin/publications" className="secondary full">Manage publications</Link></> : <><p className="section-lede">A library for ISP members. Sign in to view the covers, read the latest issues and access PDF books.</p><Link href="/member/publications" className="secondary full">Member login</Link></>}</section>;
}
